"""RPC Book Two, Titles Four to Six (Arts. 161-202): public interest, (former) opium, public morals."""

ACCESS = {'t': 'Access Devices Regulation Act (RA 8484, as amended by RA 11449)', 's': 'Punishes fraud involving credit cards and other access devices, alongside the Code’s rules on forgery.', 'u': ''}


def add(n):
    # ------------------------------------------------------------ counterfeiting, forgery, falsification
    n(161, 'Forging the Great Seal of the Government, or the signature or stamp of the Chief Executive.', chk=['Great Seal'])
    n(162, 'Knowingly using the counterfeit seal or forged signature or stamp mentioned in Art. 161.', t=['The user must not be the forger; the forger is liable under Art. 161.'], chk=['knowingly make use'])
    n(163, 'Making, importing or uttering false coins in connivance with counterfeiters or importers; the penalty depends on the kind of coin (silver of ₱1 or more, lower value, or minor coinage).', t=['A coin is false if it is forged or counterfeited, even if of equal or greater value than the genuine.'], chk=['false coins'])
    n(164, 'Mutilating coins of legal currency, or importing or uttering mutilated coins in connivance with the mutilator, with intent to defraud.', t=['Mutilation means taking off part of the metal; only coins of legal tender can be mutilated under this article.'], chk=['mutilate'])
    n(165, 'Knowingly possessing false or mutilated coins with intent to utter, or actually uttering them, without connivance with the counterfeiters.', chk=['without the connivance'])
    n(166, 'Forging or falsifying treasury or bank notes, certificates or other obligations and securities payable to bearer, or importing or uttering them in connivance with the forger.', t=['Forgery here covers obligations payable to bearer; see Art. 167 for instruments not payable to bearer.'], chk=['treasury or bank notes'])
    n(167, 'Counterfeiting, importing or uttering instruments not payable to bearer (e.g., checks payable to order) in connivance with the forger.', chk=['not payable to bearer'])
    n(168, 'Knowingly using, or possessing with intent to use, any of the false or falsified instruments in this section, when the act is not covered by the preceding articles.',
      t=['Possession of a forged treasury or bank note is not by itself a crime; intent to use must be shown.'], chk=['with intent to use'])
    n(169, 'How forgery of notes and instruments is committed: by giving a note or instrument the appearance of a true and genuine document; or by erasing, substituting, counterfeiting or altering its figures, letters, words or signs.', chk=['appearance of a true and genuine document'])
    n(170, 'Falsification of legislative documents: altering a bill, resolution or ordinance enacted or approved, or pending approval, by Congress or a local legislative body, without proper authority.', chk=['bill, resolution, or ordinance'])
    n(171, 'Falsification by a public officer, employee or notary (or ecclesiastical minister, as to records that may affect civil status) who, taking advantage of his official position, falsifies a document by any of eight acts: (1) counterfeiting or imitating a handwriting, signature or rubric; (2) causing it to appear that persons participated in an act or proceeding when they did not; (3) attributing to persons who did participate statements other than those they made; (4) making untruthful statements in a narration of facts; (5) altering true dates; (6) making alterations or intercalations that change the meaning of a genuine document; (7) issuing in authenticated form a copy of a non-existent original or one contrary to it; (8) intercalating an instrument or note in a protocol, registry or official book.',
      k=['Offender is a public officer, employee or notary.', 'He takes advantage of his official position — he has the duty to make or prepare the document, or has official custody of it.', 'He falsifies a document by one of the eight acts.', 'For mode 4: a legal obligation to disclose the truth; the facts narrated are absolutely false; wrongful intent.'],
      t=['In falsification of public or official documents, damage to a third person and intent to gain are not elements: what is punished is the violation of public faith.', 'Without abuse of official position, a public officer is liable under Art. 172 like a private individual.'],
      chk=['taking advantage of his official position', 'untruthful statements in a narration of facts'])
    n(172, 'Falsification by a private individual: (1) falsifying a public, official or commercial document by any act in Art. 171; (2) falsifying a private document, to the damage of a third party or with intent to cause damage; (3) knowingly using a falsified document — in a judicial proceeding, or, for a private document, to another’s damage.',
      k=['Public, official, commercial documents: damage not required.', 'Private documents: damage or intent to cause damage is an element.', 'Use of a falsified document: the user must know it is false; the possessor and user of a falsified document is presumed to be the falsifier if there is no satisfactory explanation.'],
      t=['Estafa through falsification of a commercial or public document is a complex crime (Art. 48). With a private document, falsification and estafa are not complexed: if falsification was the means, the crime is falsification; if the estafa was done first and the falsification only to conceal it, the crime is estafa.', 'A private document becomes a public document when notarized; falsifying a notarized deed is falsification of a public document.'],
      chk=['private individual', 'private document'])
    n(173, 'Falsification of wireless, cable, telegraph and telephone messages by officers or employees engaged in sending or receiving them, and the use of such falsified messages.', chk=['wireless, cable or telephone messages'])
    n(174, 'False medical certificates and false certificates of merit or service: a physician or surgeon who issues a false certificate; a public officer who issues a false certificate of merit, service or good conduct; and a private individual who falsifies such a certificate.', chk=['physician or surgeon'])
    n(175, 'Knowingly using any of the false certificates in Art. 174.', chk=['false certificates'])
    n(176, 'Making, introducing into the Philippines, or possessing instruments or implements for counterfeiting or falsification.', t=['Possession alone is punished; actual use is not required.'], chk=['instruments or implements'], i=[ACCESS])
    n(177, 'Usurpation of authority (knowingly and falsely representing oneself to be an officer, agent or representative of the Government or of a foreign government) and usurpation of official functions (performing, under pretense of official position, an act pertaining to a public officer without being lawfully entitled to it).',
      k=['Usurpation of authority: mere false representation is enough; no act of office is needed.', 'Usurpation of official functions: an act pertaining to the office is performed under pretense of official position.'],
      t=['The offender may be a public officer who usurps another office’s authority or functions.'], chk=['falsely represent himself', 'under pretense of official position'])
    n(178, 'Using a fictitious name publicly to conceal a crime, evade a judgment or cause damage; and concealing one’s true name and personal circumstances.',
      t=['Use of aliases is also regulated by CA 142, the Anti-Alias Law (as amended by RA 6085), which requires judicial authority for an alias other than one’s registered name.'], chk=['fictitious name'])
    n(179, 'Illegal use of uniforms or insignia: publicly and improperly using insignia, uniforms or dress of an office not held, or of a class of persons of which one is not a member.', t=['Use must be public and improper; an exact imitation is not required — a colorable resemblance that may deceive suffices.'], chk=['publicly and improperly'])
    n(180, 'False testimony against a defendant in a criminal case; the penalty depends on the sentence imposed on the defendant.', k=['A criminal proceeding.', 'Testimony against the defendant.', 'The witness knows it is false.', 'The defendant is either convicted or acquitted in a final judgment.'], t=['The defendant must at least be sentenced (or acquitted) by final judgment before prosecution; the penalty varies by the sentence.'], chk=['false testimony against the defendant'])
    n(181, 'False testimony in favor of the defendant in a criminal case.', t=['The false testimony need not actually benefit the defendant; it is enough that it was given to favor him.'], chk=['in favor of the defendant'])
    n(182, 'False testimony in civil cases; the penalty depends on the amount in controversy.', t=['The testimony must relate to the issues and be judicially given in a civil case.'], chk=['civil case'])
    n(183, 'Perjury (as amended by RA 11594, 2021): knowingly making untruthful statements under oath, or in an affidavit, on a material matter, before a competent person authorized to administer oaths, in cases where the law requires the oath. Solemn affirmations are covered. Public officers suffer the maximum period; all offenders also suffer a fine of up to ₱1,000,000 and perpetual absolute disqualification.',
      k=['A statement under oath or an affidavit on a material matter.', 'Made before a competent officer authorized to administer oaths.', 'A willful and deliberate assertion of a falsehood.', 'The sworn statement is required by law or made for a legal purpose.'],
      t=['Good faith or a lack of malice is a defense: the falsehood must be willful and deliberate.', 'RA 11594 raised the penalty to prisión mayor in its minimum period; earlier cases cite the old, lighter penalty.'],
      chk=['prision mayor in its minimum period', 'One million pesos', 'perpetual absolute disqualification'])
    n(184, 'Offering false testimony in evidence: willfully and knowingly presenting a false witness or testimony in a judicial or official proceeding (as amended by RA 11594).', t=['The offender is the one who offers the false witness, not the witness himself (who is liable under Arts. 180-183).'], chk=['willfully and knowingly offer'])
    n(185, 'Machinations in public auctions: soliciting a gift or promise to stay out of a public auction; or attempting to keep bidders away by threats, gifts, promises or other artifices, to cause a reduction of the price.', chk=['public auction'])
    n(186, 'Monopolies and combinations in restraint of trade — repealed by the Philippine Competition Act (RA 10667, 2015). Learn the Competition Act instead.', chk=['restraint of trade'])
    n(187, 'Importing, selling or disposing of articles of gold, silver or other precious metals falsely marked as to quality or fineness.', chk=['gold, silver'])
    n(188, 'Substituting and altering trademarks and trade names — repealed by the Intellectual Property Code (RA 8293), which now punishes trademark infringement and unfair competition.', chk=['substitute'])
    n(189, 'Unfair competition and fraudulent registration of trademarks — repealed by the Intellectual Property Code (RA 8293).', chk=['unfair competition'])

    # ------------------------------------------------------------ Title Five (opium) — repealed
    for a in (190, 191, 192, 193, 194):
        n(a, 'Part of the former Title Five on opium and prohibited drugs — repealed by RA 6425 (1972). Drug offenses are now governed by RA 9165 (2002), as amended.')

    # ------------------------------------------------------------ Title Six: public morals
    for a in (195, 196, 198, 199):
        n(a, 'Part of the Code’s gambling provisions (Arts. 195-199), repealed insofar as inconsistent by PD 1602 (1978). Illegal gambling is now punished under PD 1602, as amended by RA 9287 (illegal numbers games).')
    n(197, 'Betting on sports contests — repealed by PD 483 (1974), which punishes betting, game-fixing and point-shaving in sports; see also PD 1602.')
    n(200, 'Grave scandal: highly scandalous conduct offending decency or good customs, not falling under any other article.',
      k=['The act is highly scandalous, offending decency or good customs.', 'It is done publicly or comes to public knowledge.', 'It does not fall under any other article of the Code.'],
      t=['It is a residual crime: if the act is punished elsewhere (e.g., acts of lasciviousness, Art. 336), that article applies.'], chk=['highly scandalous conduct'])
    n(201, 'Immoral doctrines, obscene publications and exhibitions and indecent shows: publicly expounding doctrines contrary to public morals; authors, publishers and sellers of obscene literature; exhibitors of indecent or immoral plays or shows; and those who sell, give away or exhibit obscene films, prints and similar materials.',
      t=['Obscenity is judged by contemporary community standards: whether the work, taken as a whole, appeals to the prurient interest and lacks serious value (the Court has drawn on Miller v. California).', 'Seizure of allegedly obscene materials requires a search warrant and a judicial determination of obscenity.'],
      d=[{'n': 'Pita v. Court of Appeals', 'c': 'G.R. No. 80806, October 5, 1989', 'h': 'The warrantless seizure and burning of magazines by police as allegedly obscene was unconstitutional; obscenity must be determined by a court, and seizure requires a warrant issued on probable cause.', 'r': 'Procedure before suppressing materials as obscene.'},
         {'n': 'Fernando v. Court of Appeals', 'c': 'G.R. No. 159751, December 6, 2006', 'h': 'The Court acknowledged that obscenity resists precise definition and is judged case by case under contemporary community standards; a store owner who sold pornographic materials was convicted under Art. 201.', 'r': 'Obscenity is a judicial question decided case by case.'}],
      chk=['obscene'])
    n(202, 'Vagrants and prostitutes — repealed. RA 10158 (2012) decriminalized vagrancy, leaving only prostitution; RA 11862 (2022) then declared Art. 202 repealed. Trafficked persons are treated as victims under RA 9208, as amended.', chk=['prostitutes'])
